import {course} from './build.js';
import {L9,L10} from './healthcare-administration-final.js';
const RULES=['HOSA Healthcare Administration 2026–27 guidelines','https://hosa.org/wp-content/uploads/2026/08/HCA-26-27-FINAL-1.pdf'];
const MGMT=['OpenStax: Principles of Management','https://openstax.org/books/principles-management/pages/1-introduction'];
const WHO=['WHO: health systems governance','https://www.who.int/health-topics/health-systems-governance'];
const TEAM=['AHRQ: TeamSTEPPS','https://www.ahrq.gov/teamstepps-program/index.html'];
const IHI=['IHI: Model for Improvement','https://www.ihi.org/library/model-for-improvement'];
const PRIV=['HHS: HIPAA Privacy Rule','https://www.hhs.gov/hipaa/for-professionals/privacy/laws-regulations/index.html'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
const flip=(title,cards)=>({t:'w',kind:'flip',title,cards});

const L7={title:'Improving quality through measurement and small tests',hook:'A hospital asks staff to “be more careful” after repeated missing discharge instructions. The reminders increase, but the omissions continue. Quality improvement examines how work is designed, tests a specific change and measures whether the change actually helps.',objectives:['Distinguish quality assurance, improvement and safety investigation.','Define structure, process, outcome and balancing measures.','Apply a small Plan-Do-Study-Act cycle.','Interpret variation and select system-focused corrective actions.'],sections:[
['Quality is multidimensional',[
'High-quality care should be safe, effective, patient-centered, timely, efficient and equitable. These dimensions can interact and sometimes create tradeoffs. Reducing waiting time is useful, but a faster encounter that omits important instructions may be less safe. Efficiency means obtaining worthwhile results with appropriate resources, not merely reducing every expenditure. Equity requires examining whether avoidable differences in access or outcomes are hidden by an acceptable overall average.',
'Quality assurance checks whether defined requirements are met. Quality improvement changes processes to improve performance. Patient safety focuses on preventing and reducing harm associated with care. These activities overlap but ask different questions. An audit can establish that instructions are missing; improvement investigates why and tests a better process. Training may be part of the solution, but repeating the same instruction is unlikely to fix an unreliable handoff, poorly designed form or missing ownership.']],
['Build a useful measurement family',[
'Structure measures describe resources or arrangements, such as availability of trained staff or a functioning information system. Process measures describe what is done, such as the proportion of discharges with documented medication reconciliation. Outcome measures describe results, such as adverse events or patient understanding. A balancing measure detects unintended consequences, such as increased discharge delay or staff overtime. A project needs a small coherent set rather than dozens of unrelated indicators.',
'Operational definitions make measures reproducible. Specify the eligible population, numerator, denominator, time interval and source. “Instructions completed” might mean a form was printed, reviewed with the patient or understood by the patient; these are different events. Collect baseline data using the same definition intended for follow-up. Stratify where relevant to check whether improvement reaches patients with different language or accessibility needs. Protect privacy when small groups could become identifiable.',match('Classify the quality measure',[['Availability of trained discharge educators','Structure'],['Discharges with instructions reviewed','Process'],['Patients accurately describing the follow-up plan','Outcome'],['Extra staff time required','Balancing']])]],
['Use a small test to learn',[
'The Model for Improvement asks what the team aims to accomplish, how it will know a change is an improvement and what change it can test. An aim should define population, result and time. A change idea is a proposed mechanism, not the aim itself. “Introduce a checklist” is a change idea; “reduce omitted instructions among eligible discharges within a specified period” is an aim. Keep the distinction clear so the team can abandon an ineffective checklist without abandoning the goal.',
'Plan-Do-Study-Act tests a change on a manageable scale. Plan identifies the change, prediction, data and responsibilities. Do carries out the test and records unexpected observations. Study compares results with the prediction and examines why they differed. Act decides whether to adapt, adopt for broader testing or abandon the change. A single successful test does not establish reliable performance across shifts, populations and conditions. Increase scope as evidence and understanding improve.',{t:'w',kind:'qualitylab',title:'Test a quality improvement and inspect its tradeoffs'}]],
['Distinguish variation from a meaningful signal',[
'Every process varies. Common-cause variation arises from the routine system, while special-cause variation reflects an unusual influence. A run chart displays performance over time and can help a team look for patterns rather than react to every rise and fall. A control chart adds statistically derived limits based on an appropriate method. Control limits describe process behavior; specification limits describe desired or required performance. A stable process can still consistently fail to meet a target.',
'Do not declare improvement from one favorable week after an intervention. Examine sufficient baseline and follow-up observations, annotations for changes and the stability of definitions. Overreacting to ordinary fluctuation can make a process worse, while ignoring an unusual signal can miss an important event. Statistical tools require appropriate data and interpretation. In a HOSA case, a strong answer explains the time pattern and its limitations rather than treating any before-after difference as proof.',order('Run a small improvement test',['Define the aim and baseline measures','Plan a change with a prediction','Do a limited test and record observations','Study results against the prediction','Act by adapting, expanding or abandoning','Repeat under additional conditions'])]],
['Investigate systems and choose strong actions',[
'A process map shows steps, decisions and handoffs. A cause-and-effect diagram organizes possible contributors. Asking why repeatedly can deepen inquiry, but should not force a complex event into one simplistic root cause. A root-cause analysis examines an event retrospectively, while a failure mode and effects analysis examines possible failures prospectively. Both should lead to actions with owners and evaluation, not merely a report describing what went wrong.',
'Actions differ in reliability. Reminders and education depend heavily on memory and attention. Standardized workflows, simplified choices, better defaults and well-designed constraints may reduce dependence on vigilance. A forcing function prevents a defined action unless a required condition is met, but it must be evaluated for unintended workarounds or delays. Choose controls based on the failure mechanism and clinical context. Stronger design is not equivalent to adding more alerts, which can overwhelm attention.']],
['Test the discharge-instruction process',[
'Observe several discharges and identify where the omission occurs. Perhaps the clinician assumes a nurse printed the instructions, the nurse assumes the clinician reviewed them and the patient leaves without either step. Test explicit ownership and a shared completion status on one shift. Predict that omissions will fall without a large increase in discharge time. Collect the process measure, a patient-understanding outcome and a balancing measure for delay or workload.',
'Review both numbers and staff observations. If completion improves but understanding does not, printing or documentation may have become more reliable without improving communication. Adapt the intervention to include explanation and teach-back. If the process works only when a project leader is present, it is not yet dependable. Test weekends, staff changes and patients requiring language support before scaling. A good improvement story explains what was learned and changed, not only the final percentage.',
'Sustainability requires an owner, a standard process, training for new staff and continued monitoring proportionate to risk. Transfer successful learning carefully to other units because their workflows may differ. Include a plan for responding when performance deteriorates. Improvement is a continuing management responsibility, but monitoring should not become endless paperwork: retain measures that guide decisions and retire those that no longer provide useful information.']]
],takeaways:['A change is not an improvement until evidence supports it.','Use outcome, process and balancing measures together.','Reliable system design reduces dependence on memory alone.'],terms:[['PDSA','Plan-Do-Study-Act, an iterative test-and-learn cycle.'],['Common-cause variation','Variation arising from the routine process.']],mcqs:[q('Printing a checklist is best described as:','A change idea','An outcome by itself','Proof of improvement','A patient preference','An intervention must be evaluated against an aim.'),q('Staff overtime added by a new process is a:','Balancing measure','Primary diagnosis','Structure measure only','Randomization method','It detects an unintended burden.'),q('The Study stage of PDSA asks:','How results compare with predictions','Who should be blamed first','Which poster looks best','How to skip measurement','Study examines what the test taught.'),q('A stable process may still be:','Consistently below the desired standard','Automatically excellent','Free of every risk','Unmeasurable','Stability and acceptable performance are distinct.'),q('Control limits describe:','Expected process variation under the method','The desired target automatically','A legal threshold in every case','Patient preferences','Control limits differ from specifications.'),q('FMEA primarily examines:','Potential failures prospectively','Only one past incident','Only staff satisfaction','Only financial statements','It anticipates how a process could fail.'),q('Why may more reminders fail?','The cause may be workflow design rather than knowledge','Staff never read anything','Training is always useless','No process can improve','Actions should match the failure mechanism.'),q('Before scaling a successful test, examine:','Performance under different shifts and conditions','Only its best day','Only the project leader’s opinion','Only one completed form','Reliability must extend beyond a narrow trial.')],frq:{prompt:'Discharge instructions are repeatedly omitted despite reminders. Design a PDSA test with an aim, process/outcome/balancing measures, and a plan for interpreting and sustaining results.',rubric:[['Identify system mechanism and aim',['handoff','owner','aim']],['Use a measurement family',['process','outcome','balancing']],['Describe PDSA prediction and learning',['plan','prediction','study','act']],['Assess variation and sustainability',['time','conditions','monitor']]],model:'Observe the discharge workflow to locate unclear ownership or handoff failures. Define an aim for reducing omissions in eligible discharges over a stated interval. Test explicit ownership and a shared completion status on one shift, predicting fewer omissions without excessive delay. Measure instruction review, patient understanding and added staff time. Compare results with baseline over time and study unexpected findings. Adapt the process, test additional conditions and assign an owner, training and monitoring plan before broader adoption.'},sources:[RULES,IHI,TEAM]};

const L8={title:'Strategy, resources and achieving the mission',hook:'A hospital proposes a new service because a competitor has one. The service could attract patients, but it may divert scarce staff from the community’s most urgent needs. Strategy asks what the organization should do, why it matters and what it will stop doing to make room.',objectives:['Distinguish mission, vision, values, strategy and operations.','Use internal and external analysis without confusing lists with decisions.','Evaluate strategic options through resources, risks and opportunity costs.','Translate strategy into accountable implementation and balanced measures.'],sections:[
['Connect purpose to choices',[
'Mission describes the organization’s purpose and whom it serves. Vision describes a desired future. Values guide behavior and tradeoffs. Strategy makes choices about how the organization will achieve its purpose in a particular environment. Operations carry out the work. These concepts should connect: a strategy that contradicts the mission or cannot be implemented through daily work is only a statement. A broad aspiration such as “be the best” does not identify a meaningful choice.',
'Strategic choices include which populations to serve, which capabilities to develop, which partnerships to pursue and which activities to limit. Resources are finite, so choosing one initiative has an opportunity cost: the value of the best alternative use of those resources. A service can be attractive in isolation and still be the wrong priority. Administrators should make the tradeoff explicit rather than imply that every desirable project can be funded simultaneously.']],
['Analyze the environment and internal capability',[
'External analysis considers population needs, policy, technology, labor markets, competitors, partners and economic conditions. Internal analysis considers workforce, finances, processes, culture, assets and capabilities. A SWOT framework organizes strengths and weaknesses as internal factors and opportunities and threats as external factors. Its usefulness depends on evidence and specificity. “Good staff” is vague; “a trained outreach team with capacity for two additional clinics each week” is actionable.',
'Do not confuse the framework with the strategy. A long list of factors does not decide what to do. Link each factor to an implication: a transport barrier may support mobile services, a workforce shortage may constrain expansion and a community partnership may reduce duplication. Check assumptions with data and stakeholder perspectives, including patients and frontline staff. Competitor activity is relevant, but copying a competitor without considering the organization’s mission and capabilities can produce an expensive mismatch.',match('Separate the strategic concepts',[['Why the organization exists','Mission'],['The future it seeks','Vision'],['Principles guiding behavior','Values'],['Choices about how to achieve the purpose','Strategy']])]],
['Compare options with a business case',[
'A business case defines the problem, proposed response, alternatives, expected benefits, resources, risks and evaluation. Include the option of improving an existing service or partnering instead of building a new one. Benefits may include quality, access, experience or financial sustainability, and should be measurable where possible. Separate one-time implementation costs from recurring operating costs. Include staffing, training, maintenance, space, technology and transition disruption rather than only the purchase price.',
'A simple break-even analysis compares fixed costs with contribution per unit after variable costs. If a fictional service has fixed costs of 120,000 currency units and contribution of 60 per visit, it needs 2,000 visits to cover those fixed costs under the assumptions. This is not a complete investment decision: capacity, demand, collection, quality and opportunity cost still matter. Sensitivity analysis changes uncertain assumptions, such as volume or staffing cost, to show how fragile the conclusion may be.']],
['Manage uncertainty and dependencies',[
'A forecast is conditional on assumptions, not a promise. Scenario planning explores plausible combinations of conditions, such as slow demand growth with higher labor costs or rapid demand with a supply constraint. A risk register identifies risks, likelihood, consequences, owners and responses. Distinguish risks the organization can reduce from uncertainties it must monitor. A contingency plan specifies what action follows if a trigger occurs; simply listing “staff shortage” does not create a response.',
'Strategic initiatives often depend on other work. A new clinic may require credentialing, hiring, equipment, an information-system configuration and referral agreements. Delays in one prerequisite can affect the launch. Sequence dependencies and define decision gates where leaders review readiness. Avoid launching merely to meet a publicized date if critical conditions are unmet. At the same time, not every uncertainty justifies indefinite delay; a limited pilot may provide information while containing exposure.',order('Translate strategy into implementation',['Define mission-aligned need and options','Evaluate benefits, costs and risks','Choose priorities and allocate resources','Assign milestones, owners and dependencies','Test readiness and implement','Review outcomes and revise assumptions'])]],
['Use measures that reflect the whole strategy',[
'A balanced set of measures can include financial performance, patient or customer experience, internal processes and organizational learning or workforce capability. The exact categories should serve the strategy rather than become a ritual. Leading indicators track activities or conditions expected to influence later results; lagging indicators track outcomes after they occur. Training completion may be a leading measure, while reliable performance and patient outcomes provide stronger evidence that capability changed.',
'Each strategic objective needs an owner, a measure, a target or review criterion and a time frame. Avoid cascading so many targets that staff cannot see priorities. Measures should not encourage behavior that undermines the mission: maximizing visit volume without monitoring quality or access may reward the wrong work. Review progress in a way that supports decisions. A dashboard meeting should result in action, learning or a justified decision to continue, not only an explanation of colors.']],
['Make the new-service decision',[
'For the opening proposal, begin with community need and mission fit. Examine whether the competitor’s service reveals unmet demand or already supplies adequate capacity. Assess the organization’s clinical and operational capability, workforce constraints and alternatives such as partnership or referral coordination. Estimate demand realistically and identify which existing services would lose resources. Engage the people affected by that tradeoff, especially populations whose needs are less financially visible.',
'If the case supports a pilot, specify scope, budget, staffing, success measures and stopping criteria. Evaluate quality, access, patient experience and financial sustainability together. If the evidence does not support expansion, explain the decision using the criteria rather than personal preference. Strategy includes choosing not to pursue an appealing project when another use better serves the mission. Revisiting a decision when assumptions change is disciplined management, not necessarily inconsistency.',
'Implementation also needs a change narrative. Explain the problem, the choice made, the alternatives considered and how daily work will change. Staff should know which responsibilities remain and which priorities have been reduced to create capacity. Without this clarity, a new initiative may simply be added to an already full workload. Monitor whether promised resources arrive and whether unintended effects appear in services outside the project. A strategy succeeds through coordinated organizational behavior, not the approval of a document.']]
],takeaways:['Strategy makes choices under resource constraints.','A business case must include alternatives and recurring costs.','Implementation needs owners, dependencies, measures and review criteria.'],terms:[['Opportunity cost','Value of the best alternative use of a resource.'],['Sensitivity analysis','Testing how conclusions change when assumptions change.']],mcqs:[q('Mission primarily describes:','Purpose and whom the organization serves','Only next month’s schedule','Only a future revenue target','Only the organization chart','Mission anchors purpose.'),q('A workforce capability is usually which SWOT category?','An internal strength or weakness','Always an external threat','Always an external opportunity','None because staff never affect strategy','Capabilities are internal factors.'),q('Opportunity cost is:','Value of the best forgone alternative','Only the purchase price','A sunk cost that must be recovered','An invoice tax','Choosing one use gives up another.'),q('Fixed cost 120,000 and contribution 60 per visit gives break-even volume:','2,000 visits','720 visits','120 visits','60,000 visits','120,000/60 = 2,000.'),q('Sensitivity analysis changes:','Uncertain assumptions to assess their effect','The mission secretly','Only chart colors','Only employee names','It tests robustness of the conclusion.'),q('A risk register should include:','Owners and responses as well as risks','Only a list of fears','Only completed tasks','Only marketing claims','Risks need actionable management.'),q('Training completion alone proves:','An activity occurred, not necessarily capability or outcome improvement','Perfect performance','Patient benefit automatically','No further evaluation is needed','Completion is not the final outcome.'),q('A mission-aligned strategic decision may be to:','Decline a new service in favor of a better use of resources','Copy every competitor','Fund every proposal','Ignore community needs','Strategy includes explicit tradeoffs.')],frq:{prompt:'A hospital wants to copy a competitor’s new service despite staffing constraints. Outline a mission-based strategic evaluation and an implementation plan if a limited pilot is justified.',rubric:[['Assess need and mission fit',['mission','community','need']],['Compare options and opportunity cost',['alternative','opportunity','staff']],['Analyze resources and uncertainty',['cost','sensitivity','risk']],['Define implementation and review',['owner','milestone','measure','stop']]],model:'Assess community need, mission fit and existing capacity before assuming the competitor’s choice should be copied. Compare building, partnering and improving current services, including the opportunity cost of diverting staff. Estimate one-time and recurring costs, demand and contribution under sensitivity scenarios. If a pilot is justified, define its scope, budget, owners, dependencies and readiness gates. Track quality, access, experience, workforce burden and financial sustainability, with explicit review and stopping criteria.'},sources:[RULES,MGMT,WHO]};

const L5={title:'Teams, shared mental models and reliable performance',hook:'Five highly skilled professionals respond to a deteriorating patient. Each notices something different, but no one states the overall plan. Individual expertise is necessary; team effectiveness depends on how those observations become coordinated action.',objectives:['Distinguish a team from a collection of individuals.','Explain team development, role clarity and shared mental models.','Apply situation monitoring, mutual support and structured coordination.','Evaluate team outcomes without rewarding silence or groupthink.'],sections:[
['What makes a team',[
'A team has an interdependent purpose, complementary contributions and a need for coordinated action. A work group may share information while members largely complete separate tasks. In healthcare, teams can be stable, such as a clinic staff, or temporary, such as an emergency response team. Temporary teams cannot rely on long familiarity, so role identification and concise coordination become especially important. Membership should follow the work rather than professional status alone.',
'Define the team’s purpose in terms of the people or process it serves. “Meet every Tuesday” describes an activity, not a purpose. “Ensure every discharge has a verified medication and follow-up plan” identifies a result. A charter can specify scope, roles, decision authority, resources and measures. It should also identify what the team cannot decide and where it must escalate. A team with responsibility for a problem but no authority to change its causes may become a discussion group that absorbs time without improving care.']],
['Development and role clarity',[
'The familiar forming, storming, norming and performing model describes common patterns in team development. Members initially seek orientation, negotiate differences, establish working expectations and develop effective performance. These are useful patterns, not a mandatory linear timetable. A change in membership, task or leadership can return a mature team to earlier questions. Administrators should anticipate the need to revisit roles rather than interpret every disagreement as evidence that the team has failed.',
'Role clarity means members know their own responsibilities, understand others’ contributions and can recognize gaps. It does not mean rigidly refusing to help outside a narrow task when appropriate support is possible. Cross-training can improve awareness of dependencies while preserving professional scope. In a rapid response, one person may lead coordination, another monitor, another document and others perform defined clinical tasks. Explicit assignments prevent several people assuming that someone else has completed the same essential action.',match('Recognize team needs',[['Members do not know who coordinates the response','Role clarity'],['Members interpret the plan differently','Shared mental model'],['One member is overloaded while others can help','Mutual support'],['Changes in patient or workload are not noticed','Situation monitoring']])]],
['Build a shared mental model',[
'A shared mental model is a sufficiently aligned understanding of the situation, goals, plan and responsibilities. It does not require every professional to know every technical detail. It requires enough common understanding to anticipate actions and identify when the plan needs revision. The leader can state the current assessment, immediate priorities and assigned tasks, then invite correction. Team members should update the group when new information changes the picture.',
'Briefs establish a plan before work, huddles reassess during changing conditions, and debriefs examine what happened afterward. These functions should not be confused. A huddle is useful when the original plan no longer fits; a debrief should not be the first time anyone mentions an urgent unresolved risk. Keep coordination proportionate: a brief, focused exchange can be more useful than a long meeting that interrupts necessary care. The value comes from shared decisions and follow-through, not the meeting label.']],
['Monitor and support one another',[
'Situation monitoring involves attending to the patient or task, team status, environment and progress toward the goal. It includes noticing workload, fatigue, interruptions and equipment problems. Cross-monitoring allows members to detect potential mistakes and offer information before harm occurs. It should be framed as shared responsibility rather than surveillance designed to embarrass colleagues. A team that welcomes correction is more likely to benefit from its combined expertise.',
'Mutual support includes asking for help, offering assistance, providing useful feedback and advocating for safety. Psychological safety means people can raise concerns or acknowledge uncertainty without expecting humiliation. It does not mean every idea is accepted or standards disappear. Leaders must respond constructively to concerns and explain decisions. If a concern remains unresolved, an agreed escalation process prevents hierarchy from becoming the final answer to a clinical question.',order('Use coordination across the work cycle',['Brief the purpose, roles and initial plan','Monitor the task and team conditions','Huddle when important conditions change','Complete and confirm the handoff','Debrief outcomes and improvement actions'])]],
['Avoid predictable team failures',[
'Groupthink occurs when pressure for agreement suppresses critical evaluation. Social loafing occurs when individual effort becomes less visible within a group. Dominance by a few voices can hide information held by quieter members. A team can counter these risks through clear responsibilities, structured opportunities to contribute and explicit consideration of alternatives. Ask for independent observations before announcing a preferred answer when anchoring is a concern.',
'Diversity of expertise and experience can improve problem solving, but benefits do not occur automatically. Members need respectful communication and a way to integrate different perspectives. Conflict about evidence can be productive; personal attacks reduce trust. A leader should distinguish consensus from silence and clarify how a decision will be made. When a final decision differs from some members’ views, explain the reasoning and the conditions that would prompt reassessment.']],
['Measure effectiveness and learn',[
'Evaluate outcomes, team processes and the capacity to keep working effectively. A team can achieve a short-term target by exhausting members or discouraging reports, which is not sustainable success. Measures might include omitted handoff information, response delays, unresolved tasks, staff perceptions of speaking up and patient outcomes. Interpret reporting rates carefully: more reports may reflect greater openness rather than more unsafe care. Use multiple sources rather than one simplistic ranking.',
'In the opening response, the immediate improvement is to identify a coordinator, state the shared plan, assign tasks and confirm critical information. Afterward, debrief specific observations: what was expected, what occurred, why differences arose and what will change. Assign an owner and date to each improvement. If the action is “communicate better,” translate it into observable behavior such as naming the responsible person for every requested task and confirming completion. This makes teamwork teachable rather than a vague personal trait.',
'A useful administrative distinction is between a team problem and an organizational constraint. If every team lacks access to the same equipment or receives conflicting instructions from departments, repeated team training alone will not solve the issue. Escalate the shared constraint to those with authority over resources or policy. Team effectiveness grows when local coordination and organizational support reinforce each other.']]
],takeaways:['Expert individuals need shared purpose, roles and coordination.','Briefs, huddles and debriefs serve different moments.','Psychological safety supports high standards and honest correction.'],terms:[['Shared mental model','Aligned understanding of situation, goals and responsibilities.'],['Groupthink','Pressure for agreement that suppresses critical evaluation.']],mcqs:[q('A team differs from a collection of individuals mainly through:','Interdependence and coordinated purpose','Identical job titles','A shared room only','Equal seniority','Team work requires coordinated contributions.'),q('A huddle is primarily used to:','Reassess a plan as conditions change','Replace every initial plan','Punish a past error','Write annual budgets','Huddles update coordination during work.'),q('A debrief should produce:','Specific learning and assigned improvements','Only a general compliment','No documentation of actions','A search for one person to blame','Learning needs actionable follow-through.'),q('Psychological safety means:','People can raise concerns without humiliation','No standards apply','Every suggestion must be adopted','No one can be corrected','It supports speaking up alongside accountability.'),q('Pressure for unanimous agreement can create:','Groupthink','Perfect reasoning','Automatic expertise','Guaranteed consensus quality','Agreement pressure can suppress alternatives.'),q('More incident reports after team training may reflect:','Greater openness to reporting','Necessarily worse safety','Necessarily fraud','No meaningful information','Reporting behavior and event frequency are different.'),q('Which improves role clarity?','Name the person responsible for each essential task','Assume someone will do it','Use only job titles without assignments','Avoid discussing limits','Explicit ownership reduces omissions.'),q('A recurring equipment shortage across teams requires:','Organizational resource action as well as local teamwork','Only more motivational talks','Ignoring the common pattern','Blaming every team separately','Shared constraints need authority beyond the team.')],frq:{prompt:'An emergency team has strong individual skills but unclear coordination. Propose immediate team actions, a debrief and an organizational follow-up.',rubric:[['Establish roles and shared plan',['role','coordinator','plan']],['Monitor and support',['monitor','support','concern']],['Debrief with specific actions',['debrief','owner','action']],['Address organizational barriers',['resource','policy','organization']]],model:'Identify a coordinator, state the situation and immediate plan, assign essential tasks and confirm understanding. Encourage updates, cross-monitoring and help when workload or conditions change, with a clear escalation route for unresolved concerns. Afterward, debrief expected versus actual performance and assign concrete improvements with owners and review dates. If problems reflect shared equipment or policy constraints, escalate them to organizational leaders rather than relying only on more teamwork training.'},sources:[RULES,TEAM,MGMT]};

const L6={title:'Communication that produces shared understanding',hook:'A message saying “the patient is ready” reaches transport, pharmacy and a family member. Each interprets ready differently. Communication succeeds when the receiver understands the intended meaning and knows what action follows.',objectives:['Analyze sender, message, channel, receiver, feedback and noise.','Use structured escalation and closed-loop communication.','Adapt communication for health literacy, language and accessibility.','Create useful written, digital and crisis messages.'],sections:[
['Communication is a process, not a transmission',[
'A sender encodes a message, selects a channel and delivers it to a receiver who interprets it. Feedback helps determine whether the intended meaning arrived. Noise includes physical distractions, ambiguous words, assumptions, emotional tension and competing information. Sending a message does not establish that it was received, understood or acted upon. The phrase “ready for discharge” may mean clinically stable, paperwork complete or physically leaving; different meanings create different actions.',
'Effective communication starts with purpose and audience. Decide what the receiver needs to know, what they need to do and how urgently they need to act. Include enough context to support judgment without burying the key point. A senior leader reviewing a service proposal needs a different level of detail from a colleague coordinating an immediate task. Adapt the message without changing the facts. Concision is useful only if it preserves the information required for the decision.']],
['Choose the channel and close the loop',[
'Channels differ in speed, richness, persistence and privacy. A written message provides a record but may wait unread; a direct conversation allows immediate clarification but may need documentation afterward. Urgent or complex issues often require a synchronous channel with confirmation. Do not assume that an unread electronic message is an effective escalation simply because a timestamp proves it was sent. Follow the organization’s escalation pathway when acknowledgment or action is missing.',
'Closed-loop communication includes a clear message, receiver acknowledgment or repeat-back, and sender confirmation or correction. It is especially valuable for critical information and tasks. The goal is accurate shared understanding, not ritual repetition of every casual sentence. For a requested task, identify who will do what and by when, then confirm completion. Acknowledging receipt is different from confirming that the task has been completed.',order('Close a critical communication loop',['State the message and intended recipient','Receiver repeats or confirms key information','Sender confirms or corrects understanding','Recipient performs the agreed action','Completion or unresolved issue is reported'])]],
['Structure escalation and handoffs',[
'SBAR organizes a message into situation, background, assessment and recommendation or request. The situation states the immediate concern; background supplies relevant context; assessment summarizes what is observed or believed; the recommendation makes the needed response explicit. A structured format helps the receiver rapidly understand why the message matters. It does not authorize someone to exceed their scope or substitute a formula for clinical judgment.',
'A handoff transfers information and responsibility. It should identify the patient or task, current status, outstanding actions, anticipated problems and the person accepting responsibility. Include an opportunity for questions. Copying a long record is not equivalent to a useful handoff because the recipient must still determine what matters now. Standardization can reduce omissions, while concise narrative explains exceptions that a checklist cannot fully capture.',match('Place the SBAR component',[['The immediate issue requiring attention','Situation'],['Relevant history and context','Background'],['Current observations and interpretation','Assessment'],['The specific response requested','Recommendation or request']])]],
['Listen and adapt to the person',[
'Active listening involves attending, asking clarifying questions, reflecting meaning and checking assumptions. Avoid preparing a rebuttal while the other person is still explaining the problem. Nonverbal behavior, tone and pace affect interpretation, but should not be treated as universal cultural signals. Ask respectfully rather than inferring understanding or agreement from eye contact, silence or a nod. A person may agree politely while remaining confused or concerned.',
'Health literacy concerns the ability to find, understand and use information within the demands of a system. Plain language, small information chunks and concrete actions help many people. Teach-back asks the person to explain the plan in their own words so the professional can evaluate the explanation, not test the person’s intelligence. If understanding is incomplete, explain differently and check again. Avoid asking only “Do you understand?” because it encourages a yes response without demonstrating comprehension.']],
['Language, accessibility and digital messages',[
'Use qualified language assistance according to the setting’s policies and applicable requirements. Relying on an untrained family member for complex interpretation can create accuracy, privacy and role problems. Communicate directly with the patient and allow time for interpretation. Accessibility may require large print, screen-reader-compatible content, alternative formats or accommodations for hearing, vision or cognitive needs. A portal message is not accessible merely because it is online.',
'Written communication should use a descriptive subject, lead with the required action and separate facts from assumptions. Include dates, responsibility and a way to ask questions. Avoid unexplained abbreviations and ambiguous relative times such as “next Friday” when a specific date would prevent confusion. Protect sensitive information and use approved channels. Before sending, verify the recipient and attachments; a technically successful email can still be sent to the wrong person.']],
['Communicate during disruption and evaluate the result',[
'During a service disruption, state what is known, what is uncertain, what people should do and when an update will follow. Do not fill uncertainty with reassurance that cannot be supported. Use consistent messages across channels and designate responsibility for updates. Different audiences may need different details: patients need access instructions, staff need operational actions and leaders need decision-relevant consequences. Consistency means compatible facts, not identical wording for every audience.',
'For the opening phrase, replace “ready” with a specific state: clinical discharge approved, medication instructions pending, transport requested for a stated time. Ask the receiving service to confirm its next action. Then evaluate whether the message reduced confusion, duplicate work or delay. Communication quality is demonstrated by appropriate understanding and action, not by the number of emails sent or the length of the announcement.',
'Administrators can audit communication by following a real process and identifying where assumptions enter. Ask each role to explain what a status label means and when they consider a task complete. Differences often reveal hidden workflow defects. Revise the shared terminology and test it with new staff and patients, who are less likely to fill gaps from experience. A reliable message should not require years of insider knowledge to interpret correctly.']]
],takeaways:['Sent, received, understood and completed are different states.','Structured communication supports clear action and responsibility.','Teach-back evaluates the explanation, not the patient.'],terms:[['Closed loop','Message, acknowledgment and confirmation with follow-through.'],['Teach-back','Checking understanding by asking the person to explain the plan in their own words.']],mcqs:[q('A sent message proves:','Only that a transmission action occurred','That it was understood','That its task is complete','That the recipient agreed','Receipt and action need separate confirmation.'),q('The R in SBAR identifies:','Recommendation or request','Revenue','Registration','Randomization','It states the response needed.'),q('Which channel is often best for urgent ambiguous information?','A synchronous channel with confirmation','An unmonitored inbox only','A poster added later','A vague group message','Immediate clarification and acknowledgment matter.'),q('Teach-back asks the person to:','Explain the plan in their own words','Repeat a professional title','Promise they understand','Pass a literacy test','It checks how well the explanation worked.'),q('A handoff includes transfer of:','Information and responsibility','Only a copied record','Only a bed number','Only a timestamp','The receiver must know what they own next.'),q('Silence from a patient necessarily means agreement?','No, understanding and preferences should be checked','Yes in every culture','Only online','Yes if the visit is short','Nonverbal behavior is context dependent.'),q('During a disruption, a useful message includes:','Known facts, uncertainty, actions and update timing','Unsupported reassurance','Only technical jargon','No next step','People need actionable and honest information.'),q('Which is more precise than “ready”?','Clinical discharge approved; medication teaching pending','All good','Done soon','Ready enough','Specific status separates completed and outstanding work.')],frq:{prompt:'A vague discharge message causes pharmacy, transport and the family to act at different times. Redesign the communication and explain how you will verify understanding and completion.',rubric:[['Specify status and outstanding work',['status','pending','specific']],['Choose channel and close loop',['confirm','repeat','channel']],['Clarify responsibility',['who','responsibility','time']],['Adapt for patient understanding',['plain','teach-back','language']]],model:'Replace “ready” with explicit completed and pending steps, including clinical approval, medication teaching and transport timing. Send the message through a channel appropriate to urgency and obtain acknowledgment of each service’s responsibility and expected completion. Confirm completion separately from receipt. Explain the patient plan in plain language with qualified language support when needed, and use teach-back to check understanding. Review delays or duplicate actions to determine whether the revised message works.'},sources:[RULES,TEAM,MGMT]};

const L3={title:'Organization design and coordination across boundaries',hook:'A patient waits for discharge because pharmacy, transport and the ward each completed their own work but nobody coordinated the final sequence. The organization chart shows authority. It does not necessarily show how a patient moves through the system.',objectives:['Compare functional, divisional, service-line and matrix structures.','Explain specialization, formalization and centralization.','Analyze coordination mechanisms and handoff failures.','Design responsibility and escalation across departments.'],sections:[
['Structure distributes work and decisions',[
'Organization design divides work and establishes how the parts reconnect. Specialization groups expertise, formalization specifies procedures, centralization concentrates decision authority and hierarchy establishes reporting relationships. Each choice creates benefits and costs. Specialization can improve technical skill but create silos. Formal procedures support consistency but may be too rigid for unusual situations. Central decisions can promote standardization while slowing local responses if every exception requires approval far from the work.',
'Span of control describes the number of direct reports overseen by a manager. A wider span can reduce layers but may exceed the manager’s capacity when work is complex or staff need intensive support. A narrower span allows more supervision but adds coordination overhead. There is no universally correct number independent of task, experience and resources. Evaluate whether the manager can provide meaningful direction, feedback and support rather than assuming a flatter structure is always more efficient.']],
['Compare structural options',[
'A functional structure groups work by expertise, such as nursing, finance, pharmacy or information technology. It supports professional development and shared standards but can make cross-functional coordination difficult. A divisional structure groups work around products, regions or populations, giving each division a more complete set of resources. It can improve responsiveness while duplicating support functions. A service line organizes attention around a clinical area or patient pathway, such as cardiovascular care, across traditional departments.',
'A matrix combines dimensions, often a professional or functional reporting line with a project or service-line relationship. This can connect expertise and patient-centered goals, but dual expectations create ambiguity if priorities conflict. The answer is not merely to tell employees to cooperate. Specify which manager controls staffing, professional standards, budgets and day-to-day priorities, and how disagreements are resolved. A matrix without decision rules can turn every routine choice into a negotiation.',match('Recognize the structure',[['Group all finance staff by expertise','Functional'],['Organize separate regional operations','Divisional'],['Coordinate cardiovascular care across departments','Service line'],['Combine functional and project reporting','Matrix']])]],
['Coordination mechanisms complement the chart',[
'Organizations coordinate through rules, shared plans, direct supervision, standardized skills and mutual adjustment. A routine medication-reconciliation step may use a standard process; an unexpected complex discharge may need a real-time interdisciplinary discussion. The mechanism should fit uncertainty and interdependence. Highly variable work cannot be fully scripted, while repeatedly negotiating a stable routine wastes time. Good design identifies which parts need consistency and which need informed flexibility.',
'Liaison roles, case managers, cross-functional teams and shared information systems can connect departments. However, a coordinator needs authority, access and a clear mandate. Creating a new role without removing contradictory expectations can add another handoff. Shared metrics also matter. If transport is rewarded only for vehicle utilization and the ward only for bed turnover, neither metric may capture timely, safe patient departure. A pathway measure can reveal whether local optimization is harming the overall process.']],
['Map dependencies and responsibility',[
'Sequential interdependence means one task’s output becomes another’s input. Reciprocal interdependence involves repeated exchange, as when clinicians and rehabilitation staff revise a plan together. Pooled interdependence occurs when units contribute to a shared result without every task directly feeding the next. These patterns suggest different coordination needs. A simple checklist may work for a stable sequence but be inadequate for reciprocal clinical problem solving.',
'A responsibility matrix can distinguish who performs a task, who is accountable for its completion, who is consulted and who is informed. Use it to clarify a specific process, not to produce a decorative spreadsheet. Avoid assigning several competing accountable owners for one decision without explaining the final authority. Equally, avoid making one person accountable for an entire pathway without giving them the means to coordinate it. Escalation rules should state when a delay or disagreement requires a higher-level decision.',order('Redesign a cross-department process',['Map the patient journey and dependencies','Identify delayed handoffs and conflicting goals','Assign task ownership and decision authority','Agree on shared information and escalation','Test the redesigned sequence','Review pathway outcomes and adjust'])]],
['Formal and informal organizations both matter',[
'The formal organization includes approved positions, policies and reporting lines. The informal organization includes relationships, trusted experts and communication patterns that emerge in practice. Informal networks can help solve problems quickly, but relying only on personal relationships makes a process fragile when key people are absent. An administrator should learn how work actually happens, then preserve useful collaboration while establishing reliable processes that do not depend on knowing the right person.',
'Culture affects whether people use the coordination mechanisms provided. Staff may avoid escalating a problem if previous escalation led to blame, or may bypass a committee that never makes decisions. Structural redesign therefore requires attention to incentives and behavior. Moving boxes on a chart does not automatically change trust, information flow or workload. Explain why the change is needed, involve affected roles and evaluate whether decisions actually become clearer.']],
['Repair the discharge sequence',[
'Map the discharge from the patient’s perspective: clinical readiness, final instructions, medication access, transport confirmation and handoff to the next setting. Identify which tasks can happen in parallel and which require a completed prior step. A shared readiness view can prevent pharmacy from waiting for information that the ward assumes was already sent. Assign a coordinator for exceptions, while retaining each profession’s responsibility for its own clinical work.',
'Test the new sequence on a limited group and measure time from clinical readiness to departure, missing information, patient understanding and staff burden. A faster discharge is not automatically better if medications or follow-up are missing. Review delays by cause rather than blaming whichever department appears last in the sequence. The durable outcome is a system in which responsibilities and dependencies are visible, staff can escalate problems and the patient receives a coherent transition even when individual employees change.',
'Before adopting a service line, also ask how it will interact with shared resources. A cardiovascular program may need operating rooms, imaging and intensive-care capacity also used by other services. If each service line independently maximizes its own volume, shared bottlenecks can worsen. Establish transparent prioritization rules and a forum that can resolve tradeoffs across the organization. Design should make these conflicts discussable rather than conceal them behind separate budgets.']]
],takeaways:['Structure divides work; coordination reconnects it.','Every structural choice has tradeoffs.','Shared pathway goals can reveal failures hidden by departmental success.'],terms:[['Span of control','Number of direct reports overseen by a manager.'],['Matrix','A structure combining two dimensions of authority or reporting.']],mcqs:[q('Grouping staff by expertise is a:','Functional structure','Geographic division necessarily','Pure patient registry','Payment model','Functions concentrate expertise.'),q('A matrix often creates:','Dual expectations requiring clear decision rules','No reporting relationships','No need for coordination','Only one possible manager','Multiple dimensions can create priority conflicts.'),q('Span of control refers to:','Number of direct reports','Number of hospital beds','Length of a shift','Size of a patient record','It describes supervisory breadth.'),q('A stable routine may benefit most from:','A clear standardized process','Repeated unrestricted negotiation','No documentation','A new committee for every case','Standardization reduces unnecessary variation.'),q('Repeated exchange between professions is:','Reciprocal interdependence','No interdependence','Only pooled finance','A staffing ratio','Reciprocal work requires ongoing adjustment.'),q('Local departmental targets can harm:','Overall pathway performance','Only the organization chart','Only stationery costs','Nothing if each unit meets its target','Local optimization can create system delays.'),q('An informal network can be useful but fragile because:','It may depend on particular relationships','It always violates policy','It eliminates hierarchy','It guarantees equal access','Processes should not depend entirely on personal contacts.'),q('A faster discharge should be checked against:','Medication access, understanding and safe follow-up','Only departure time','Only bed count','Only transport mileage','Speed is one dimension of a safe transition.')],frq:{prompt:'Pharmacy, transport and a ward meet their own targets but patients wait for discharge. Propose an organization-design and coordination response.',rubric:[['Map interdependencies',['handoff','sequence','dependency']],['Clarify authority and ownership',['owner','authority','accountable']],['Align pathway measures',['shared','pathway','measure']],['Test safety and burden',['test','medication','understanding']]],model:'Map the discharge pathway and identify sequential dependencies and conflicting local targets. Clarify who performs each task, who coordinates exceptions and how unresolved delays are escalated. Create a shared readiness view and pathway measures such as time from clinical readiness to safe departure. Test the change with a limited group, checking medication access, patient understanding and staff burden alongside speed. Retain professional responsibilities while making cross-department coordination reliable.'},sources:[RULES,MGMT,TEAM]};

const L4={title:'Motivation, fairness and constructive conflict',hook:'A manager offers a prize for the highest number of completed calls. Call volume rises, but patients report rushed conversations and unresolved questions. Motivation systems can improve performance or redirect effort toward the wrong target.',objectives:['Compare intrinsic and extrinsic motivation.','Apply expectancy, equity and goal-setting ideas.','Distinguish task, process and relationship conflict.','Use a structured response to conflict without suppressing safety concerns.'],sections:[
['Understand what people are being asked to do',[
'Motivation concerns the direction, intensity and persistence of effort. Intrinsic motivation arises from interest, mastery or meaning in the work; extrinsic motivation relates to consequences such as pay, recognition or advancement. Both can matter. Healthcare staff may care deeply about patients while also needing fair pay, reasonable workload and reliable schedules. Treating purpose as a substitute for adequate working conditions can undermine trust rather than inspire commitment.',
'A manager should distinguish motivation from capability and opportunity. A person may want to perform well but lack training, equipment, information or time. Asking for more effort does not fix an impossible workload or an inaccessible system. Before interpreting low performance as unwillingness, ask whether expectations are clear, skills are sufficient and the environment permits success. This diagnosis determines whether the appropriate response is coaching, redesign, resources or an accountability conversation.']],
['Use motivation theories as diagnostic tools',[
'Expectancy theory examines whether effort is believed to produce performance, whether performance produces an outcome and whether the outcome is valued. If a scheduling system repeatedly fails, an employee may doubt that extra effort will improve results. If recognition is arbitrary, the performance-to-outcome link is weak. If the reward is unwanted, its value is low. A useful intervention strengthens the broken link rather than adding a reward to every situation.',
'Equity theory emphasizes perceived fairness in the relationship between contributions and outcomes compared with relevant others. Fairness also includes procedures and interpersonal treatment: people may accept an unfavorable decision more readily when the process is transparent, consistent and respectful. Goal-setting research emphasizes clear, challenging but attainable goals with feedback. Goals should not be so narrow that they encourage harmful shortcuts. A call-volume target needs accompanying expectations for accuracy, resolution and patient experience.',match('Identify the motivational issue',[['Extra effort cannot overcome a broken system','Weak effort-to-performance expectancy'],['Good work receives unpredictable recognition','Weak performance-to-outcome link'],['The offered reward is unwanted','Low value of the outcome'],['Comparable work receives unexplained unequal treatment','Perceived inequity']])]],
['Design work and feedback well',[
'Job design can increase meaningfulness through task variety, understanding the whole contribution and seeing the effect on patients. Appropriate autonomy lets staff exercise judgment within their scope. Feedback should be timely, specific and tied to observable behavior. “Be more professional” is vague; “Confirm the callback plan before ending the call” describes an action that can be practiced. Recognize effective work without turning every activity into a competition that discourages cooperation.',
'Performance conversations should separate observation from interpretation. Describe what happened, ask for the employee’s perspective and identify barriers. Agree on a concrete improvement and support, then schedule review. If the concern involves safety or misconduct, follow appropriate procedures and do not dilute accountability. Fairness means responding proportionately and consistently, not treating every mistake, reckless act and system failure as identical. An environment that learns from honest error can still maintain clear behavioral standards.']],
['Conflict has different sources',[
'Task conflict concerns ideas or goals, process conflict concerns how work is organized, and relationship conflict concerns interpersonal tension. Disagreement about evidence can improve a decision when managed respectfully. Personal attacks and unresolved resentment can impair coordination. A manager should identify the subject and context before selecting a response. A dispute about weekend coverage may appear personal while reflecting an unclear or inequitable scheduling rule.',
'Common conflict responses include avoiding, accommodating, competing, compromising and collaborating. Avoidance can be useful for a brief cooling-off period but is dangerous when it suppresses an urgent safety concern. A directive response may be necessary during an immediate emergency, with later review. Compromise divides differences, while collaboration explores interests and seeks a solution addressing the underlying needs. No style is universally best; urgency, stakes, relationships and available time matter.',flip('Choose the distinction',[['Disagreement about which evidence supports a protocol','Task conflict'],['Disagreement about who performs a handoff','Process conflict'],['Personal hostility unrelated to the task','Relationship conflict'],['A short pause followed by a planned discussion','Potentially constructive temporary avoidance']])]],
['Move from positions to interests',[
'A position is a stated demand, such as “I must never work Saturday.” An interest is the need behind it, such as childcare, transport or recovery from a second obligation. Ask open questions, summarize each perspective and identify shared goals. Separate facts from assumptions and agree on objective criteria. A schedule might be redesigned using transparent rotation, advance notice and a process for exceptions. Collaboration does not guarantee that every preference can be met, but it can make tradeoffs explicit.',
'Document the agreed action, responsibility and review date. If power differences make direct discussion unsafe or ineffective, use the appropriate supervisor, human resources or other formal channel. Do not pressure someone to negotiate away a safety, discrimination or harassment concern as though it were merely a difference in style. Confidentiality and procedural fairness matter. The manager’s role includes knowing when a conflict exceeds an informal conversation.']],
['Redesign the call-center incentive',[
'The opening prize rewards speed and volume while ignoring whether calls achieve their purpose. Replace the single target with a balanced view: timely contact, accurate information, resolved questions, appropriate escalation and patient experience. Observe whether staff have enough time and resources to meet those expectations. Involve staff in identifying which measures reflect good work and which can be gamed. Recognition can support teamwork, learning and reliable follow-through rather than only ranking individuals.',
'Monitor unintended effects after the change. If complex calls lower an employee’s apparent productivity, account for case mix rather than rewarding avoidance of difficult patients. If documentation expands, ensure it adds useful information rather than consuming time needed for care. Explain how feedback will be used and provide a route to question errors. Motivation is strongest when people can see a credible connection between effort, meaningful performance, fair treatment and outcomes they value.',
'A useful test of an incentive is to imagine a clever employee maximizing the metric while ignoring its purpose. If that behavior would harm patients or coworkers, the metric needs redesign. Also ask whether the incentive displaces existing cooperation: a prize for individual volume may discourage helping a colleague with a difficult call. This counterfactual analysis reveals weaknesses before they become routine behavior.']]
],takeaways:['Performance depends on capability and opportunity as well as motivation.','Rewards can create shortcuts when targets are narrow.','Constructive conflict addresses interests, facts and fair procedures.'],terms:[['Expectancy','Belief that effort can lead to the required performance.'],['Interest','The underlying need behind a stated position.']],mcqs:[q('A broken system prevents success despite effort. The main issue is:','Opportunity and expectancy','Lack of character necessarily','Excessive intrinsic motivation','Too much recognition','Effort cannot overcome every system barrier.'),q('A reward nobody wants has low:','Valence or value','Specificity','Staffing','Clinical acuity','An outcome must be valued to motivate.'),q('A volume-only incentive may produce:','Rushed work and neglected quality','Guaranteed quality','No behavioral change','Automatic equity','People may optimize the measured target.'),q('Disagreement over who performs a handoff is mainly:','Process conflict','Only relationship conflict','A diagnostic error','A financing model','The dispute concerns organization of work.'),q('An underlying childcare need is an:','Interest','Outcome metric','Formal sanction','Inventory item','Interests explain positions.'),q('Which feedback is most actionable?','Confirm the callback plan before ending each call','Be better','Show more spirit','Stop being difficult','It identifies an observable behavior.'),q('Avoidance is inappropriate when it:','Suppresses an urgent safety concern','Allows a brief planned cooling-off period','Prevents a needless argument temporarily','Is followed by timely review','Safety concerns need an effective response.'),q('Fair treatment requires:','Consistent, transparent and respectful processes','Identical outcomes regardless of context','No accountability','Rewards based on favoritism','Procedural and interpersonal fairness matter.')],frq:{prompt:'A call-volume prize increases rushed conversations and team conflict. Diagnose the incentive problem and propose a motivation and conflict-management response.',rubric:[['Explain narrow incentives',['volume','quality','incentive']],['Assess barriers and fairness',['resources','fair','workload']],['Use constructive conflict methods',['interest','listen','criteria']],['Define balanced feedback and review',['resolution','feedback','review']]],model:'The prize makes volume the visible reward while neglecting accuracy and resolution. Assess workload, system barriers and case complexity before attributing problems to attitude. Discuss staff interests and perceived fairness using observable facts and shared service goals. Replace the single metric with balanced expectations for timely contact, accurate information, resolution and patient experience, and recognize cooperation. Agree on actions and review dates, monitor gaming or avoidance of complex calls, and use formal channels for concerns that exceed ordinary disagreement.'},sources:[RULES,MGMT,TEAM]};

const L1={title:'Healthcare delivery systems in a connected world',hook:'A rural clinic cannot obtain a common supply after a disruption thousands of miles away. At the same time, its patients struggle to reach appointments only twenty miles away. Healthcare administration must understand both global interdependence and local access.',objectives:['Distinguish financing, insurance, delivery and regulation.','Compare service levels and coordination across settings.','Analyze global workforce, supply-chain and population pressures.','Evaluate access, quality, cost and equity together.'],sections:[
['Separate the functions of a health system',[
'A health system includes the people, organizations, resources and rules that support health. Financing concerns how money is raised and distributed. Insurance pools financial risk across people. Delivery concerns where and by whom services are provided. Regulation and governance establish requirements, accountability and oversight. These functions can be arranged differently within and across countries. Public financing does not necessarily mean every provider is a public employee, and private delivery does not imply that every patient pays the full cost directly.',
'A simple comparison should ask who is covered, which services are included, how providers are paid and what patients must contribute. A system described with a single label may contain many arrangements. Coverage on paper also differs from effective access: a person may have insurance but face long travel, unavailable clinicians, language barriers or unaffordable cost sharing. Administrators need to understand the actual path to care rather than treating enrollment as proof that needs are met.']],
['Coordinate levels and settings of care',[
'Primary care provides an accessible point for continuing, broad health needs and coordination. Secondary care generally involves specialist services, while tertiary care provides highly specialized services. These levels describe function rather than quality rankings. A primary-care team can provide excellent care, and a specialized hospital can fail to coordinate a basic transition. Prevention, acute treatment, rehabilitation, long-term support and palliative care also occur across different settings and stages of illness.',
'Transitions create risk because responsibility and information move between organizations. A hospital discharge may require medication access, home support, follow-up and transport. If each organization optimizes only its own task, the patient can still experience a broken process. An administrator should map the full journey, identify handoffs and clarify who confirms completion. Coordination may require shared agreements, compatible information systems and payment arrangements that support work occurring between visits.',match('Separate system functions',[['Collect and allocate funds','Financing'],['Pool financial risk','Insurance'],['Provide clinical services','Delivery'],['Set oversight and accountability','Governance']])]],
['Payment creates incentives and tradeoffs',[
'Fee-for-service pays for defined services and can reward activity without directly rewarding coordination or outcomes. Capitation pays a defined amount for a covered person over a period, creating incentives to manage overall resource use but also requiring safeguards against inadequate service. Bundled payment groups services around an episode. Salaries, budgets and performance-linked arrangements create other incentives. No payment method automatically guarantees value; behavior depends on design, measurement and the surrounding system.',
'For a fictional diabetes program, paying only for visits may leave care coordination unfunded even if coordination prevents complications. Paying a fixed amount may support flexible outreach but create pressure to limit resources. Administrators should examine quality, access and financial consequences together. Risk adjustment may account for some differences in patient need, but imperfect measurement can still create incentives to avoid complex patients. Transparent eligibility and monitoring protect against judging success only by lower expenditure.']],
['Global connections affect local operations',[
'Supply chains cross borders through raw materials, manufacturing, transport and distribution. A low-cost single supplier may become a single point of failure. Resilience can involve diversified sources, appropriate inventories, substitution protocols and communication with clinical teams. Stockpiling every item is not feasible because storage, expiration and capital have costs. Prioritize supplies according to clinical criticality, lead time, alternatives and the consequences of interruption.',
'Workforce migration can expand opportunity and fill shortages while also affecting the communities from which professionals leave. Training capacity, working conditions, recognition of credentials and retention all matter. Population aging and chronic disease change service demand, while infectious threats and disasters can cross jurisdictions quickly. Administrators must distinguish predictable long-term demand from sudden surge needs. International cooperation and local readiness are complementary: a global surveillance system does not replace a clinic’s continuity plan.',order('Assess a critical supply risk',['Identify the clinical function of the supply','Map supplier and transport dependencies','Assess alternatives and disruption consequences','Choose proportionate reserves and backup arrangements','Test communication and substitution procedures'])]],
['Evaluate access and performance fairly',[
'Access has multiple dimensions: availability of services, geographic reach, affordability, acceptability and the ability to navigate care. A digital appointment system may improve convenience for some patients while excluding those without connectivity or accessible devices. Ask who benefits and who is left out. Average waiting time should be examined alongside differences by location, language or other relevant circumstances, while protecting privacy. Equity analysis is about identifying avoidable barriers, not assuming every group has identical needs.',
'Performance must balance quality, experience, population outcomes, workforce sustainability and cost. Lower spending caused by unmet need is not necessarily efficiency. Higher spending may reflect waste, greater need or better access; the number alone cannot distinguish these explanations. Compare similar populations using clearly defined measures, and investigate context before ranking organizations. A useful administrative recommendation identifies the mechanism by which a change improves care and the measure that would show whether it worked.']],
['Apply the system view to the rural clinic',[
'For the supply disruption, identify essential services at risk, consult clinical teams about approved alternatives and communicate honestly about availability. Review supplier concentration and reorder assumptions after the immediate problem is controlled. For travel barriers, examine appointment timing, transport partnerships, outreach and suitable remote services. A remote service still requires a plan for patients who need examination, testing or urgent escalation. Technology should fit the clinical task rather than become a universal substitute.',
'The two problems share a lesson: access depends on connected processes. A full shelf does not help a patient who cannot reach the clinic, and an appointment does not help if essential supplies are absent. Build a small set of measures that follows the entire service: canceled visits due to supply shortages, missed visits associated with transport, time to completed care and patient experience. Assign owners to both operational fixes and longer-term system changes.']]
],takeaways:['Financing, delivery and governance are distinct functions.','Coverage is not the same as effective access.','Resilience requires explicit tradeoffs and connected workflows.'],terms:[['Capitation','Payment per covered person for a defined period.'],['Care transition','Movement of responsibility and care between settings or teams.']],mcqs:[q('Public financing necessarily means all providers are public employees?','No, financing and delivery can be arranged separately','Yes in all systems','Only for specialist care','Only for primary care','Funding and ownership are distinct.'),q('Insurance primarily pools:','Financial risk','Only medical supplies','Only employee schedules','Only patient records','Risk pooling spreads uncertain costs.'),q('Primary care is best described as:','Broad continuing care and coordination','Inferior-quality care','Only emergency surgery','Only inpatient rehabilitation','Level describes function, not quality.'),q('Fee-for-service primarily rewards:','Defined service activity','Guaranteed outcomes','Zero utilization','Equal access automatically','Payment follows billed services.'),q('Capitation creates a need to monitor:','Under-service and access as well as costs','Only visit counts','Only building size','Only logo recognition','Fixed payment can influence service provision.'),q('A single low-cost supplier can create:','A concentrated disruption risk','Guaranteed resilience','No inventory needs','Automatic clinical equivalence','One source may become a single point of failure.'),q('Insurance enrollment alone does not establish:','Effective access to needed care','A financing arrangement','A coverage record','Potential financial protection','Travel, availability and other barriers can remain.'),q('Lower spending should be interpreted with:','Need, quality and access','Only the budget target','Only a competitor ranking','Only the payment label','Reduced spending can reflect unmet need as well as efficiency.')],frq:{prompt:'A rural clinic faces supply disruption and transport barriers. Propose a system-level response that addresses immediate continuity, financing or delivery incentives, and equity-sensitive measures.',rubric:[['Address supply dependencies and continuity',['supplier','alternative','continuity']],['Address effective access',['transport','access','remote']],['Recognize incentives and tradeoffs',['payment','cost','tradeoff']],['Measure outcomes and equity',['measure','completed','barrier']]],model:'Identify essential services threatened by the supply shortage, arrange approved alternatives and review backup suppliers and inventory tradeoffs. Map transport barriers and consider scheduling changes, partnerships or appropriate remote services with escalation plans. Examine whether payment supports coordination and outreach rather than only visits. Track canceled care, time to completed service, patient experience and differences in access across relevant groups. Assign owners and evaluate whether the changes improve completed care without creating unsustainable costs or new barriers.'},sources:[RULES,WHO,MGMT]};

const L2={title:'Leadership and the management framework',hook:'A new manager can write a clear schedule but cannot persuade the team to adopt a safer handoff. Another inspires enthusiasm but never assigns responsibilities. Effective healthcare leadership needs direction, relationships and disciplined management.',objectives:['Apply planning, organizing, leading and controlling.','Compare leadership approaches and sources of influence.','Distinguish authority, accountability and delegation.','Choose a leadership response appropriate to task, risk and team capability.'],sections:[
['Four functions form a continuing cycle',[
'Planning defines objectives, assumptions and actions. Organizing arranges work, resources and responsibility. Leading influences people toward shared goals. Controlling compares performance with expectations and supports corrective action. These functions interact rather than occurring once in a perfect sequence. A staffing shortage may require a revised plan, different work allocation, supportive leadership and closer monitoring at the same time. “Control” in this framework means feedback and adjustment, not simply punishment.',
'For a new discharge process, planning identifies the problem and target; organizing assigns tasks and resources; leading explains the purpose and engages the team; controlling checks whether discharges are safer and adjusts the process. A failure in any function can undermine the others. A clear goal without resources produces frustration, while abundant resources without a defined goal can produce activity that does not improve care.']],
['Authority and leadership are not identical',[
'Formal authority comes from an organizational position and its assigned decision rights. Leadership is influence that can also come from expertise, trust, example or relationships. A respected experienced nurse may influence practice without holding a management title. A formal manager still needs credibility to obtain honest information and sustained cooperation. Positional authority can require compliance with a legitimate policy, but it cannot automatically create commitment or reveal hidden workflow problems.',
'Power can arise from legitimate role, rewards, coercion, expertise or identification with a respected person. These sources have different consequences. Expertise supports reasoned influence when the person recognizes its limits. Threats may produce short-term compliance while discouraging reporting. Rewards can reinforce useful behavior but can also distort priorities if poorly designed. In healthcare, influence should be evaluated by its effect on safety, trust and responsible performance, not only whether people obey quickly.',match('Match the management function',[['Set the discharge improvement target','Planning'],['Assign resources and responsibilities','Organizing'],['Build shared commitment','Leading'],['Compare results and adjust','Controlling']])]],
['Compare leadership approaches',[
'Transactional leadership emphasizes expectations, exchanges and performance consequences. Transformational leadership emphasizes shared purpose, development and change. Servant-oriented leadership emphasizes supporting others and removing barriers. Participative approaches involve team members in decisions, while directive approaches specify actions more tightly. These are lenses for analyzing behavior, not mutually exclusive personality labels. A leader can communicate a vision and still establish clear operational expectations.',
'Situational approaches adapt direction and support to the task and the person’s readiness or capability. A novice using an unfamiliar high-risk process may need explicit instruction and close supervision; an experienced team solving a workflow problem may benefit from autonomy and participation. Contingency thinking asks how effectiveness depends on the setting. The lesson is not to choose a fashionable style, but to explain why a particular behavior fits the task, urgency, expertise and risks.']],
['Delegate work without losing accountability',[
'Delegation assigns an appropriate task and authority to another person while clarifying expectations, limits and follow-up. It is not abandonment. The delegating manager must consider competence, workload, legal or professional scope and available support. Instructions should describe the expected result, deadline, resources and conditions requiring escalation. The recipient should have an opportunity to clarify and confirm understanding. Assigning responsibility without the authority or resources to act is a common organizational failure.',
'Accountability means being answerable for decisions and results. Responsibility describes the work assigned, and authority describes permitted decisions. These should align. A coordinator cannot be held fairly accountable for securing appointments if no one permits them to contact the relevant service or access scheduling information. Conversely, broad authority without clear accountability can lead to inconsistent decisions. Document the arrangement in a practical way and review progress at an interval proportionate to the task.',order('Delegate a defined task',['Assess task risk and recipient capability','Specify the expected result and limits','Provide authority, resources and support','Confirm understanding and escalation triggers','Review results and give feedback'])]],
['Use judgment under uncertainty',[
'Managers rarely have complete information. They must distinguish reversible decisions that can be tested from high-consequence decisions needing more evidence or formal review. Bounded rationality recognizes limits in time and information. A structured decision process identifies the problem, generates alternatives, evaluates consequences and chooses an action with a review plan. Satisficing means selecting an acceptable option under constraints; it should not become an excuse to ignore obvious safety requirements.',
'Common traps include confirmation bias, overconfidence and escalation of commitment to a failing plan. Seek disconfirming evidence, ask what would change the decision and invite concerns from people closest to the work. A leader who admits uncertainty can still provide clear direction: “We will test this on one shift, monitor these outcomes and stop if these problems occur.” That is more accountable than pretending the plan cannot fail.']],
['Lead the safer-handoff change',[
'The opening managers each have an incomplete approach. Combine a concrete plan with a credible explanation of why the handoff matters. Observe the current process, involve receiving and sending staff, define the required information and test the new method in a limited setting. Provide training and time to practice. Clarify who leads the handoff, who confirms understanding and how unresolved concerns are escalated. The leader’s role is to remove barriers as well as announce expectations.',
'Monitor quality of the handoff and consequences such as delays or missing information. Thank staff for reporting problems, then respond visibly so reporting feels worthwhile. If compliance is low, investigate usability, workload and understanding before assuming resistance. Hold people accountable for clear, supported expectations while improving the system around them. Sustainable leadership connects purpose with daily work, creates a way to learn and makes follow-through visible.']]
],takeaways:['Management functions reinforce one another.','Influence depends on more than formal authority.','Delegation requires capability, authority, support and review.'],terms:[['Accountability','Being answerable for decisions and results.'],['Situational leadership','Adapting direction and support to task and capability.']],mcqs:[q('Comparing actual results with a target is primarily:','Controlling','Recruiting only','Financing','Branding','Controlling uses feedback to adjust performance.'),q('A respected clinician without a title can exercise:','Informal leadership','No influence','Only legal authority','Automatic budget control','Influence can arise from expertise and trust.'),q('A novice on an unfamiliar high-risk task may need:','Clear direction and close support','Complete unsupported autonomy','No feedback','Only a motivational slogan','Support should fit capability and risk.'),q('Delegation should include:','Expected results, authority and escalation limits','Only a task name','No review','Responsibility without resources','Delegation requires a workable arrangement.'),q('Transformational leadership emphasizes:','Shared purpose and development','Only punishment','Only payroll','Only routine exchange','It emphasizes vision and change.'),q('Continuing a failing project because much was already invested illustrates:','Escalation of commitment','Random sampling','Successful delegation','Perfect control','Past investment can distort future decisions.'),q('Authority without accountability risks:','Unclear answerability for decisions','Automatic safety','Elimination of conflict','Perfect coordination','Decision rights need corresponding responsibility.'),q('Low adoption of a new process should first prompt:','Investigation of barriers and understanding','An assumption of bad character','Immediate removal of all staff','Ignoring safety reports','Adoption depends on design, support and context.')],frq:{prompt:'A team resists a new handoff process. Use the four management functions, a suitable leadership approach and a delegation plan to respond.',rubric:[['Apply four management functions',['plan','organize','lead','control']],['Adapt support to team and task',['participation','support','risk']],['Align authority and accountability',['authority','responsibility','delegate']],['Monitor and learn',['feedback','measure','barrier']]],model:'Plan around a clearly defined handoff problem and measurable goal. Organize roles, time and training, then lead through a clear safety purpose and meaningful staff participation. Delegate specific tasks with authority, resources and escalation limits, adapting supervision to experience and risk. Control the process by reviewing missing information, delays and feedback. Investigate workload or usability barriers rather than assuming unwillingness, and adjust the implementation while maintaining supported expectations.'},sources:[RULES,MGMT,TEAM]};

L1.sections.at(-1)[1].push('Continuity planning should identify which services can be postponed and which require an alternative immediately. Establish those priorities with clinical input before a disruption, then review them as conditions change. A pre-agreed process reduces rushed decisions and makes communication with patients more consistent.');
L2.sections.at(-1)[1].push('Leadership succession also affects reliability. If the handoff improvement depends entirely on one enthusiastic manager, staff may abandon it when that person leaves. Build expectations into orientation, role descriptions and routine review, while preserving a way to suggest improvements. Develop other team members who can coach the process and explain its purpose. This distributes capability rather than merely distributing tasks. The leader should be able to step away without the work losing its direction, support or feedback loop.');
L6.sections.at(-1)[1].push('Check whether the recipient can identify both the immediate action and the condition requiring further contact. A message that communicates only the first step may still leave the next exception unmanaged.');
export default course('Healthcare Administration',{intro:'Ten connected lessons cover the complete HOSA administration blueprint: systems, leadership, organizational design, people, teams, communication, quality, strategy, policy and ethics.',units:[{title:'Systems, leadership and organization',summary:'Understand delivery and design coordinated organizations.',lessons:[L1,L2,L3]},{title:'People, teams and communication',summary:'Motivate fairly and turn expertise into coordinated action.',lessons:[L4,L5,L6]},{title:'Quality and strategic execution',summary:'Test improvements and direct resources toward the mission.',lessons:[L7,L8]},{title:'Policy, consumers and ethical responsibility',summary:'Connect compliance, patient experience and responsible decisions.',lessons:[L9,L10]}]});

